# Install-TailAdmin-OneShot.ps1
# Run as Administrator from ANY folder.
#   powershell -NoProfile -ExecutionPolicy Bypass -File .\Install-TailAdmin-OneShot.ps1
$ErrorActionPreference = 'Stop'
$App = 'C:\RPM-Assure\App'
$ServiceName = 'RPMAssure-App'
$Drop = 'C:\RPM-Assure\_drop'
$PackZip = Join-Path $Drop 'RPMAssure-TailAdmin.zip'

function W($c,$m){ Write-Host $m -ForegroundColor $c }

Write-Host '========================================' -ForegroundColor Cyan
Write-Host ' RPM Assure - TailAdmin UI one-shot'
Write-Host '========================================' -ForegroundColor Cyan

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) { throw 'Run as Administrator.' }
if (-not (Test-Path $App)) { throw "Missing $App" }

New-Item -ItemType Directory -Force -Path $Drop | Out-Null

$found = $null
$scriptDir = $null
if ($PSCommandPath) { $scriptDir = Split-Path -Parent $PSCommandPath }
elseif ($MyInvocation.MyCommand.Path) { $scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path }

$look = @()
if ($scriptDir) {
  $look += (Join-Path $scriptDir 'RPMAssure-TailAdmin.zip')
}
$look += (Join-Path $env:USERPROFILE 'Downloads\RPMAssure-TailAdmin.zip')
$look += $PackZip
foreach ($p in $look) {
  if ($p -and (Test-Path -LiteralPath $p)) { $found = $p; break }
}

if ($found) {
  W Green ("Using zip: $found")
  if ($found -ne $PackZip) { Copy-Item -LiteralPath $found -Destination $PackZip -Force }
} else {
  W Cyan 'No zip in Downloads - writing embedded pack...'
