'@
  $bytes = [Convert]::FromBase64String(($b64 -replace '\s',''))
  [IO.File]::WriteAllBytes($PackZip, $bytes)
  W Green ("Wrote $PackZip (" + $bytes.Length + " bytes)")
}

$extract = Join-Path $Drop 'tailadmin-pack'
if (Test-Path $extract) { Remove-Item -LiteralPath $extract -Recurse -Force }
New-Item -ItemType Directory -Force -Path $extract | Out-Null
Expand-Archive -LiteralPath $PackZip -DestinationPath $extract -Force
$appSrc = Join-Path $extract 'App'
if (-not (Test-Path (Join-Path $appSrc 'src\styles.css'))) {
  throw 'Extracted pack missing App\src\styles.css'
}

$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$bakDir = "C:\RPM-Assure\backup\tailadmin_$stamp"
New-Item -ItemType Directory -Force -Path $bakDir | Out-Null

Get-ChildItem -LiteralPath $appSrc -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($appSrc.Length).TrimStart('\')
  $dest = Join-Path $App $rel
  $bak = Join-Path $bakDir ($rel -replace '\\','_')
  if (Test-Path -LiteralPath $dest) { Copy-Item -LiteralPath $dest -Destination $bak -Force }
  $destDir = Split-Path -Parent $dest
  if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Force -Path $destDir | Out-Null }
  Copy-Item -LiteralPath $_.FullName -Destination $dest -Force
  W Green ("Installed $rel")
}
W Green "Backup: $bakDir"

$svcObj = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
if ($svcObj) {
  W Cyan ("Restarting {0} (was {1}) ..." -f $ServiceName, $svcObj.Status)
  Restart-Service -InputObject $svcObj -Force
  $up = $false
  for ($i = 1; $i -le 40; $i++) {
    Start-Sleep -Seconds 1
    $l = Get-NetTCPConnection -LocalPort 8081 -State Listen -ErrorAction SilentlyContinue
    if ($l) { W Green ("LISTENING PID {0}" -f $l[0].OwningProcess); $up = $true; break }
  }
  if (-not $up) { W Yellow 'Service restarted but port not listening yet.' }
  Get-Service -Name $ServiceName | Format-Table Name, Status, StartType -AutoSize
} else {
  W Yellow 'Service RPMAssure-App not found - files installed.'
}

try {
  $r = Invoke-WebRequest -Uri 'http://127.0.0.1:8081/login' -UseBasicParsing -TimeoutSec 8
  W Green ("PROOF OK: /login HTTP {0}" -f $r.StatusCode)
} catch {
  W Yellow ("PROOF: /login not ready yet - {0}" -f $_.Exception.Message)
}

Write-Host ''
Write-Host '========================================' -ForegroundColor Green
Write-Host ' INSTALLED - TailAdmin UI'
Write-Host '  Hard-refresh the browser (Ctrl+F5)'
Write-Host '========================================' -ForegroundColor Green
